'use strict';
// Карточка контрагента
/* ── Counterparty card ── */
// Отменённые и удалённые операции (вид с «_x») остаются в истории, но в OPK их нет — в деньгах и списках они не участвуют.
// «Отменить списание» и «Отменить возврат» — то же, что «Удалить» в окне операции (ТЗ «Окно оплаты»)
function woUndoDlg(o){opDelDlg({src:'op',ref:o})}
const woActs=o=>['bonus','refund'].includes(o.kind)?opActs({src:'op',ref:o},false).filter(x=>x.danger):[];
// «Оплатил контрагент сам» (v57): оплата налога вида 'pay' с self — своя подпись; деньги на наших счетах не меняются, поэтому знака нет
const OP_SELF=['Оплата контрагентом напрямую','faint',''];const opk=o=>o.self&&o.kind.startsWith('pay')?OP_SELF:OPK[o.kind];
const OPK={in:['Поступление','green','+'],pay:['Оплата налога','blue','−'],bonus:['Списание в бонус','purple','−'],refund:['Возврат контрагенту','orange','−'],back:['Возврат по уточнённому','green','+'],corr:['Обратная запись','yellow',''],xfer:['Перевод на счёт сотрудника','gray','']};
function openCp(c,tab){
  openModal({size:'wide',live:true,state:{tab:tab||'main',period:ym(TODAY)},render:m=>{
    const st=m.state;const cTasks=feat('tasks')?allTasks().filter(t=>t.cp===c.id&&(t.reg?OPEN.has(t.status):taskOpen(t))).length:0;const cProj=PROJECTS.filter(p=>p.cp===c.id).length;const cFiles=feat('files')?allFiles().filter(x=>x.cp===c.id).length:0;
    const tabs=[['main','Основное','building'],can('repView')?['reports','Отчёты к сдаче','file',c.overdue||'',true]:null,c.kind!=='oneoff'&&can('repView')?['pick','Подбор отчётов','list']:null,feat('taxpay')&&(can('finView')||can('money'))&&(seeAll('fin')||c.resp===S.me)?['money','Деньги','wallet']:null,feat('fee')&&can('fee')&&c.kind!=='oneoff'?['fee','Обслуживание','coins']:null,feat('projects')&&can('projView')?['projects','Проекты','briefcase',cProj||'']:null,feat('tasks')?['tasks','Задачи','task',cTasks||'']:null,feat('indicators')&&can('kpiView')&&c.kind!=='oneoff'?(()=>{const x=!c.archived&&kMissCnt().by[c.id];return ['kpi','Показатели','gauge',x?x.ms.length:'',x?(x.over||'yellow'):false]})():null,feat('files')&&can('filesView')?['files','Файлы','clip',cFiles||'']:null,['hist','История','history']].filter(Boolean);
    if(!tabs.find(t=>t[0]===st.tab))st.tab='main';
    let b='';
    if(st.tab==='main'){const ta=c.assign.filter(a=>!a.to);b=`<div class="box">${scaleFull('svc',c.status,c.id)}${statusHistHtml('svc',c)?`<details class="sh-d"><summary>${ic('history','sm')}История статусов<span class="grow"></span>${ic('down','sm')}</summary>${statusHistHtml('svc',c)}</details>`:''}</div>${c.kind!=='oneoff'||c.gked?gkNote(c):''}<div class="box"><div class="kv">
      ${gkKv(c)}<div><span class="k">ИНН</span><span class="v mono">${c.inn}</span></div>${auditKv(c)}<div><span class="k">Телефон</span><span class="v">${phoneHtml(c.phone)}</span></div>
      <div><span class="k">Форма собственности</span><span class="v">${esc(c.form)}</span></div><div><span class="k">Режим налогообложения</span><span class="v">${c.regime?esc(REGIME_FULL[c.regime]||c.regime)+(c.regime2?` <span class="faint">+ дополнительный:</span> ${esc(REGIME_FULL[c.regime2]||c.regime2)}`:''):`<span class="pill yellow">${ic('alert')}не указан</span><div class="hint">Доступны все виды отчётов, назначение проверяется вручную</div>`}</span></div>
      <div><span class="k">Льготы и особые статусы</span><span class="v">${benLine(c)} <button class="linkbtn" id="cp-ben" style="font-size:12px">${can('createCp')&&!c.archived?'выбрать':'описания'}</button>${benSoon(c).map(b=>`<div class="note warn" style="margin-top:6px">${ic('alert')}<span>Льгота «${esc(b.name)}» по кодексу заканчивается ${fmtD(b.until)} (через ${diffDays(b.until,TODAY)} дн.): проверьте ставки и назначенные отчёты.</span></div>`).join('')}</span></div>
      ${sfCardKv(c)}${c.kind!=='oneoff'?`<div><span class="k">Основания для отчётов</span><span class="v">${(c.bases||[]).length?esc(c.bases.map(k=>(baseOf(k)||{}).name||k).join(', ')):'<span class="faint">нет</span>'}</span></div><div><span class="k">Размер бизнеса</span><span class="v">${esc(bizName(c.size||'small'))}</span></div>`:''}
      <div><span class="k">Налоговый орган (УГНС)</span><span class="v">${can('createCp')&&!c.archived?sel('cp-ugns',[['','— не указан —'],...DICT.ugns.items.filter(x=>x.active||ugK(x)===c.ugns).map(x=>[ugK(x),ugT(x)])],c.ugns||'','style="min-height:30px;padding:3px 8px"'):esc(ugnsLabel(c.ugns)||'не указан')}</span></div>
      <div><span class="k">Тип обслуживания</span><span class="v">${c.kind==='oneoff'?'Разовое <span class="hint">только разовые услуги и проекты</span>':'Постоянное'}</span></div>
      <div><span class="k">Статус обслуживания</span><span class="v">${pill(c.status,SVST)}<div class="hint">Периоды обслуживания: ${esc(periodsText(c))}</div></span></div>
      <div><span class="k">Руководитель</span><span class="v">${esc(c.head||'—')}</span></div><div><span class="k">Контактное лицо</span><span class="v">${esc(c.contact||'—')}</span></div>
      <div><span class="k">Начало обслуживания</span><span class="v">${fmtD(c.start)}</span></div><div><span class="k">Договор</span><span class="v">${esc(c.contract||'—')}</span></div>${feat('fee')&&can('fee')&&c.kind!=='oneoff'?`<div><span class="k">День оплаты обслуживания</span><span class="v">до ${c.feeDay} числа месяца</span></div>`:''}${c.note?`<div><span class="k">Примечание</span><span class="v" style="white-space:pre-wrap">${esc(c.note)}</span></div>`:''}
      <div><span class="k">Ответственный бухгалтер</span><span class="v">${c.resp?esc(EM[c.resp].fio):'<span class="pill orange">'+ic('alert')+'не назначен</span>'}${can('assign')||can('createCp')?` <button class="linkbtn" id="cp-resp" style="font-size:12px">сменить</button>`:''}</span></div>
      ${feat('taxpay')&&feat('fee')&&can('fee')&&c.kind!=='oneoff'?`<div><span class="k">Платит одной суммой${tipI('Контрагент переводит одну сумму сразу на налоги и обслуживание. Система сама делит её: сначала налоги, остаток — в оплату обслуживания.')}</span><span class="v"><label class="row" style="gap:8px"><input type="checkbox" class="sw" id="cp-one" ${c.oneSum?'checked':''} ${can('createCp')&&!c.archived?'':'disabled'}> налоги и обслуживание вместе</label><span class="hint">При поступлении деление на налоги и обслуживание подставится само</span></span></div>`:''}
      ${feat('taxpay')?`<div><span class="k">Файл при поступлении</span><span class="v"><label class="row" style="gap:8px"><input type="checkbox" class="sw" id="cp-needf" ${c.needInFile?'checked':''} ${can('createCp')&&!c.archived?'':'disabled'}> обязательно требовать</label><span class="hint">Поступление от контрагента нельзя сохранить без скрина перевода или квитанции</span></span></div>`:''}
      ${feat('taxpay')?`<div><span class="k">Деньги на налоги переводит</span><span class="v">${can('createCp')?sel('cp-pays',[['emp','на кошелёк ответственного'],['org','на счёт организации']],c.paysTo,'style="min-height:30px;padding:3px 8px"'):c.paysTo==='org'?'на счёт организации':'на кошелёк ответственного'}</span></div>`:''}
    </div></div>${regKvBox(c)}
    <div class="box"><h3>Сдаёт отчёты · ${ta.length}<span class="grow"></span>${c.kind!=='oneoff'?`<button class="btn sm" id="cp-pick" title="Открыть вкладку «Подбор отчётов»">${ic('list','sm')}Подбор отчётов</button>`:''}${can('assign')&&ta.length?`<button class="btn sm" id="cp-assign" title="Ставки, повторяющиеся суммы и периодичность">${ic('sliders','sm')}Ставки</button>`:''}</h3>${pkNotNeededNote(c,ta.map(a=>a.t),pkEdit(c)?'data-nnrm':'')}${ta.length?`<div class="tbl-wrap"><table class="mini m-cards cp-asg"><thead><tr><th>Вид отчёта</th><th>Орган</th><th>Срок сдачи</th><th>Ставка</th><th class="num">Повторяющаяся сумма</th><th>С</th><th>По</th><th>Ответственный</th><th>Примечание</th>${can('assign')?'<th></th>':''}</tr></thead><tbody>${ta.map(a=>{const t=T[a.t],te=tEff(t,a,c);return `<tr><td title="${esc(t.name)}"><b>${esc(t.short)}</b> <span class="faint">${esc(t.code)}</span></td><td>${esc(t.organ)}</td><td class="wrap">${esc(ruleText(te))}${te.ovBen?` <span class="tag" title="Срок задаёт статус «${esc(te.ovBen)}»">по статусу</span>`:''}${t.oneOff?' <span class="tag">разовый</span>':''}${perOwn(t)?` <span class="tag">${PER_LABEL[te.per].toLowerCase()}</span>`:''}${t.payOnly?' <span class="tag">только оплата</span>':''}</td><td>${esc(aRateTxt(a,t)||'—')}${sfTypeIds().includes(a.t)&&sfState(c)?`<div class="hint">взносы: ${esc(sfName(c))}${sfState(c).cur&&sfState(c).cur.total?' · '+esc(sfState(c).cur.total):''}</div>`:''}</td><td class="num">${a.fixed!=null?`${ic('repeat','sm')} ${fmtM(a.fixed)}`:'<span class="faint">—</span>'}</td><td>${esc(ymLabel((a.from||TODAY).slice(0,7)))}</td><td>${a.until?esc(ymLabel(a.until)):'<span class="faint">—</span>'}</td><td>${esc(empName(a.resp||c.resp))}${a.resp?' <span class="tag">отдельно</span>':''}</td><td>${a.note?esc(a.note):'<span class="faint">—</span>'}</td>${can('assign')?`<td><button type="button" class="icon-btn sm" data-asg="${a.t}" title="Изменить назначение" aria-label="Изменить назначение ${esc(t.short)}">${ic('edit','sm')}</button></td>`:''}</tr>`}).join('')}</tbody></table></div>`:`<span class="faint">Виды отчётов не назначены${can('assign')?': нажмите «Изменить», чтобы выбрать':''}</span>`}</div>
    ${pgBox(c)}${feat('taxpay')&&can('money')?`<div class="box flat"><h3>Баланс по контрагенту</h3><div class="kv">${(()=>{const s=(k,self)=>OPS.filter(o=>o.cp===c.id&&o.kind===k&&(self==null||!!o.self===self)).reduce((a,o)=>a+o.amount,0);return `<div><span class="k">Получено от контрагента</span><span class="v tnum">${som(s('in')+s('back')+s('corr'))}</span></div><div><span class="k">Оплачено в бюджет</span><span class="v tnum">${som(s('pay'))}${s('pay',true)?`<div class="hint">из них контрагент оплатил сам: ${som(s('pay',true))}</div>`:''}</span></div><div><span class="k">Списано в бонус</span><span class="v tnum">${som(s('bonus'))}</span></div><div><span class="k">Остаток на счёте</span><span class="v tnum strong">${som(c.avail)}</span></div>${feat('fee')&&can('fee')?`<div><span class="k">Долг за обслуживание</span><span class="v tnum ${c.feeDebt?'red strong':''}">${som(c.feeDebt)}</span></div>`:''}`})()}</div></div>`:''}`}
    if(st.tab==='reports')b=`<div id="cpr"></div>`;
    if(st.tab==='pick')b=pkCpTab(c,st);
    if(st.tab==='money'){const months=[-2,-1,0,1].map(k=>addMonths(ym(TODAY),k));const pm=st.period;
      const need=REPORTS.filter(r=>r.cp===c.id&&!r.superseded&&tR(r).sum&&r.sum>0&&r.paid<r.sum&&r.status!=='Не требуется'&&r.payDue&&r.payDue<=lastDay(pm)).sort((a,b)=>a.payDue<b.payDue?-1:1);
      const needSum=need.reduce((a,r)=>a+r.sum-r.paid,0);const have=c.avail;
      // Деньги, принятые под отчёты со сроком оплаты позже выбранного месяца, — отдельной строкой; «Излишек» — только из свободных денег
      const later=REPORTS.filter(r=>r.cp===c.id&&r.ear>0&&r.payDue&&r.payDue>lastDay(pm)).sort((a,b)=>a.payDue<b.payDue?-1:1);const laterSum=later.reduce((a,r)=>a+r.ear,0);
      const diff=Math.round((have-laterSum-needSum)*100)/100;
      // Неактивные «Списать в бонус» и «Вернуть остаток» объясняют причину при наведении, на телефоне — при нажатии
      const noFree=c.free>0?'':c.avail>0?`Свободного остатка нет: ${som(c.avail-Math.max(0,c.free))} нужны на неоплаченные налоги`:'Свободного остатка нет: денег контрагента на счёте нет';
      const ops=OPS.filter(o=>o.cp===c.id&&OPK[o.kind]).sort((a,b)=>a.date<b.date?1:-1);
      b=`<div class="row cp-per"><span class="muted">Сверка по сроку оплаты до конца месяца:</span>${sel('cp-per',months.map(k=>[k,ymLabel(k)]),pm,'style="width:auto;min-height:30px;padding:3px 8px"')}</div>
        <div class="plates static">${plate({id:'need',icon:'file',color:needSum?'yellow':'green',label:'Нужно оплатить',value:fmtM(needSum,false),unit:'сом',sub:need.length?`отчётов: ${need.length}`:'неоплаченных нет'})}${plate({id:'have',icon:'wallet',color:'blue',label:'Поступило и не потрачено',value:fmtM(have,false),unit:'сом',sub:c.paysTo==='org'?'на счёте организации':'на счёте сотрудника'})}</div>
        ${diff<0?`<div class="verdict short">${ic('alert')}<span>Недостача</span><span class="big">${fmtM(-diff)}</span></div>`:diff===0?`<div class="verdict ok">${ic('ok')}<span>Достаточно</span><span class="big">${fmtM(0)}</span></div>`:`<div class="verdict ${needSum?'ok':'over'}">${ic(needSum?'ok':'info')}<span>${needSum?'Достаточно, излишек':'Излишек'}</span><span class="big">+${fmtM(diff)}</span></div>`}
        ${laterSum?`<div class="note cp-later">${ic('clock')}<span>Отложено под отчёты с более поздним сроком: <b>${som(laterSum)}</b> (${later.map(r=>`${esc(T[r.t].short)} ${esc(r.plabel)}, до ${fmtD(r.payDue)}`).join('; ')})</span></div>`:''}
        <div class="row acts"><div class="grow"></div>${c.archived||!can('money')?'':`<button class="btn sm cta" id="cp-in">${ic('plus','sm')}<span class="bl">Поступление</span></button>`}${feat('accounts')&&(c.archived?can('archiveRest'):can('bonus'))&&c.paysTo==='emp'?`<button class="btn sm ${noFree?'dis':''}" id="cp-bonus" ${noFree?`aria-disabled="true" data-why="${esc(noFree)}" title="${esc(noFree)}"`:'title="Списать в бонус"'} aria-label="Списать в бонус">${ic('gift','sm')}<span class="bl">Списать в бонус</span></button>${tipI('Свободный остаток денег контрагента после оплаты всех налогов можно списать сотруднику как бонус. Списания попадают в ежемесячный отчёт.')}`:''}${(!c.archived&&can('money'))||(c.archived&&can('archiveRest'))?`<button class="btn sm ${noFree?'dis':''}" id="cp-refund" ${noFree?`aria-disabled="true" data-why="${esc(noFree)}" title="${esc(noFree)}"`:'title="Вернуть остаток"'} aria-label="Вернуть остаток">${ic('refresh','sm')}<span class="bl">Вернуть остаток</span></button>`:''}${!c.archived&&can('money')&&seeAll('fin')&&orgHeld(c)>0&&c.resp?`<button class="btn sm" id="cp-xfer" title="Перевод" aria-label="Перевод">${ic('send','sm')}<span class="bl">Перевод</span></button>${tipI('Деньги контрагента со счёта организации можно перевести на счёт его ответственного бухгалтера: общий остаток контрагента не меняется.')}`:''}</div>
      ${c.archived&&c.free>0?`<div class="note warn">${ic('alert')}<span>Контрагент в архиве, остаток ${som(c.free)}. ${can('archiveRest')?'Решите: вернуть контрагенту или списать в бонус.':'Что с ним сделать, решает владелец.'}</span></div>`:''}
      <div class="box"><h3>Что нужно оплатить · ${need.length}</h3>${need.length?`<div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Отчёт</th><th>Срок оплаты</th><th class="num">Осталось</th></tr></thead><tbody>${need.map(r=>`<tr class="clk" data-rep="${r.id}"><td>${esc(T[r.t].short)} · ${esc(r.plabel)}</td><td class="${r.payDue<TODAY?'red strong':''}">${fmtD(r.payDue)}</td><td class="num">${fmtM(r.sum-r.paid)}</td></tr>`).join('')}<tr class="m-total"><td><b>Итого</b></td><td></td><td class="num"><b>${fmtM(needSum)}</b></td></tr></tbody></table></div>`:'<span class="faint">Неоплаченных налогов с таким сроком нет</span>'}<div class="hint">${c.paysTo==='org'?'Деньги на счёте организации; тратит их ответственный бухгалтер этого контрагента.':`Деньги на счёте сотрудника ${esc(empName(c.resp).replace(/\.$/,''))}.`} Налог контрагента оплачивается только его деньгами.</div></div>
      <div class="box"><h3>Операции · ${ops.length}</h3><div class="tbl-wrap"><table class="mini m-cards" data-mt="1"><thead><tr><th>Дата</th><th>Операция</th><th>Основание</th><th>Автор</th><th class="num">Сумма</th></tr></thead><tbody>${ops.map(o=>`<tr class="clk" data-opw="op:${o.id}" title="Открыть операцию"><td>${fmtD(o.date)}</td><td><span class="pill sm ${opk(o)[1]}">${opk(o)[0]}</span>${o.edited?' <span class="tag yellow">изменена</span>':''}</td><td class="wrap">${esc(o.note||'—')}</td><td>${esc(whoName(o.by))}</td><td class="num ${opk(o)[2]==='+'?'green':''}">${o.kind==='corr'?(o.amount<0?'−':'+'):opk(o)[2]}${fmtM(Math.abs(o.amount))}</td></tr>`).join('')||'<tr><td colspan="5" class="faint">Операций пока не было</td></tr>'}</tbody></table></div><span class="hint">Нажмите на операцию — откроется её окно: там видно, кто и когда её внёс, и её можно изменить или удалить с причиной.</span></div>`}
    if(st.tab==='fee'){const ct=curTariff(c);const months=feeMonths(c).reverse();const fps=FEEPAYS.filter(f=>f.cp===c.id&&!f.del).sort((a,b)=>a.date<b.date?1:-1);
      b=`<div class="plates static">${plate({id:'tar',icon:'coins',color:'blue',label:'Текущая ставка',value:ct?fmtM(ct.amount,false):'—',unit:'сом '+(ct&&ct.per==='Y'?'в год':'в месяц'),sub:ct?ct.per==='Y'?`ежегодно, начисление раз в год в ${MONTHS[+ct.from.slice(5)-1].replace(/ь$/,'е').replace(/й$/,'е').replace(/т$/,'те')}, оплата до ${c.feeDay}-го числа`:`с ${ymG(ct.from)}, оплата до ${c.feeDay}-го`:''})}${plate({id:'debt',icon:'alert',color:c.feeDebt?'red':'green',label:'Долг за обслуживание',value:fmtM(c.feeDebt,false),unit:'сом',sub:(c.feeDebt?'срок оплаты прошёл':'долгов нет')+(c.feeAdv?` · аванс ${fmtM(c.feeAdv,false)}`:'')})}</div>
      <div class="row acts"><div class="grow"></div>${can('tariff')?`<button class="btn sm" id="cp-tariff" title="Новая ставка" aria-label="Новая ставка">${ic('plus','sm')}<span class="bl">Новая ставка</span></button>`:''}${c.feeDebt?`<button class="btn sm" id="cp-feewa" title="Напомнить в WhatsApp" aria-label="Напомнить в WhatsApp">${ic('chat','sm')}<span class="bl">Напомнить в WhatsApp</span></button>`:''}${feeAccOk(c)?`<button class="btn sm cta" id="cp-feepay">${ic('wallet','sm')}<span class="bl">Принять оплату за обслуживание</span></button>`:''}</div>
      <div class="cols2"><div class="box"><h3>Начисления и оплаты</h3><div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Месяц</th><th class="num">Начислено</th><th class="num">Оплачено</th><th>Статус</th></tr></thead><tbody>${months.filter(mm=>feeCharge(c,mm)>0||c.feePaid[mm]).map(mm=>{const ch=feeCharge(c,mm),p=feeGot(c,mm);const due=feeDue(c,mm);const stx=p>=ch?'Оплачено':p>0?'Оплачено частично':'Не оплачено';const av=(c.feeAdvUse||{})[mm];return `<tr><td>${ymLabel(mm)}${mm===c.start.slice(0,7)&&c.start.slice(8)!=='01'?' <span class="tag" title="Первый неполный месяц">с '+(+c.start.slice(8))+'-го</span>':''}</td><td class="num">${fmtM(ch)}</td><td class="num">${fmtM(p)}${av?` <span class="tag" title="Засчитано из аванса ${esc(som(av))}">из аванса</span>`:''}</td><td>${p<ch&&due<TODAY?`<span class="pill red">${ic('alert')}${stx}</span>`:pill(stx,PST)}</td></tr>`}).join('')}</tbody></table></div></div>
      <div class="box"><h3>Оплаты · ${fps.length}</h3>${fps.length?`<div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Дата</th><th>За месяц</th><th>Внёс</th><th class="num">Сумма</th></tr></thead><tbody>${fps.slice(0,24).map(f=>`<tr class="clk" data-opw="fee:${esc(f.id)}" title="Открыть оплату"><td>${fmtD(f.date)}</td><td>${esc(ymLabel(f.month))}${f.op?' <span class="tag">из общего поступления</span>':''}${f.edited?' <span class="tag yellow">изменена</span>':''}</td><td>${esc(whoName(f.by))}</td><td class="num">${fmtM(f.amount)}</td></tr>`).join('')}</tbody></table></div>${fps.length>24?`<span class="hint">Показаны последние 24; все оплаты — в «Финансовых операциях», вкладка «Обслуживание»</span>`:''}`:'<span class="faint">Оплат пока не было</span>'}</div>
      <div class="box"><h3>Журнал тарифов</h3><ul class="tl">${c.tariffs.slice().sort((a,b)=>a.from<b.from?1:-1).map(t=>`<li><span class="t">с ${esc(ymG(t.from))}</span><span><b class="tnum">${som(t.amount)}</b> ${t.per==='Y'?'в год':'в месяц'}<br><span class="w">${esc(t.note||'')} · ${esc(whoName(t.by))}, ${fmtD(t.at)}</span></span></li>`).join('')}</ul><span class="hint">Записи не удаляются и не переписываются: новая ставка всегда добавляется новой записью и действует с 1-го числа.</span></div></div>`}
    if(st.tab==='tasks'){const all=allTasks().filter(t=>t.cp===c.id).sort((a,b)=>a.date<b.date?1:-1);const ts=all.slice(0,40);const nm=' — '+c.name;const ttl=t=>t.title.endsWith(nm)?t.title.slice(0,-nm.length):t.title;const add=feat('tasks')&&can('tasksCreate')&&!c.archived;
      b=ts.length?`<div class="row acts"><span class="muted">Задач: ${all.length}${cTasks?` · открытых ${cTasks}`:''}</span><div class="grow"></div>${add?`<button class="btn sm cta" id="cc-task">${ic('plus','sm')}<span class="bl">Задача</span></button>`:''}</div><div class="box"><div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Задача</th><th>Исполнитель</th><th>Срок</th><th>Статус</th></tr></thead><tbody>${ts.map(t=>`<tr class="clk" data-task="${t.id}"><td class="wrap">${t.reg?'<span class="tag">регулярная</span> ':''}${esc(ttl(t))}</td><td>${esc(empName(t.exec))}</td><td class="${taskOver(t)?'red strong':''}">${fmtD(t.date)}</td><td>${pill(t.status,TST)}</td></tr>`).join('')}</tbody></table></div>${all.length>ts.length?`<span class="hint">Показаны последние ${ts.length}; все задачи — в модуле «Задачи»</span>`:''}</div>`
        :`<div class="state">${ic('task','lg')}<b>Задач по контрагенту пока нет</b><span>Регулярные задачи появятся сами по назначенным отчётам; ручную задачу можно поставить сейчас.</span>${add?`<button class="btn cta" id="cc-task">${ic('plus')}Задача</button>`:''}</div>`}
    if(st.tab==='kpi')b=kpiCardHtml(c,st);
    if(st.tab==='files'){const fs=allFiles().filter(x=>x.cp===c.id);const att=can('filesUpload')?`<label class="btn sm ${fs.length?'':'cta'}" style="cursor:pointer">${ic('clip','sm')}Прикрепить<input type="file" id="cp-file" multiple hidden></label>`:'';
      b=fs.length?`<div class="row acts"><span class="muted">Документов: ${fs.length}</span><div class="grow"></div>${att}</div><div class="box"><div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Файл</th><th>Откуда</th><th class="num">Размер</th></tr></thead><tbody>${fs.map(x=>`<tr class="clk" data-file="${esc(x.id)}"><td class="wrap">${ic('file','sm')} ${esc(x.name)}</td><td class="muted">${esc(x.src)}</td><td class="num muted">${fmtSize(x.size)}</td></tr>`).join('')}</tbody></table></div><span class="hint">Сюда собраны файлы контрагента, его отчётов, оплат, услуг и проектов. Те же файлы видны в модуле «Файловый менеджер».</span></div>`
        :`<div class="state">${ic('clip','lg')}<b>Документов пока нет</b><span>Здесь соберутся файлы контрагента, его отчётов, оплат, услуг и проектов.</span>${att}</div>`}
    if(st.tab==='fin')b=`<div class="row acts"><span class="muted">Все деньги этого контрагента: налоги, обслуживание, проекты и разовые услуги</span><div class="grow"></div>${can('projects')&&!c.archived?`<button class="btn sm" id="cp-svc" title="Разовая услуга" aria-label="Разовая услуга">${ic('plus','sm')}<span class="bl">Разовая услуга</span></button>`:''}${feat('taxpay')&&can('money')&&!c.archived?`<button class="btn sm cta" id="cp-in2">${ic('plus','sm')}<span class="bl">Поступление</span></button>`:''}</div><div id="cpf"></div>`;
    if(st.tab==='projects'){const ps=PROJECTS.filter(p=>p.cp===c.id);const add=can('projects')&&!c.archived;
      b=ps.length?`<div class="row acts"><span class="muted">Проектов: ${ps.length}</span><div class="grow"></div>${add?`<button class="btn sm cta" id="cp-proj">${ic('plus','sm')}<span class="bl">Новый проект</span></button>`:''}</div><div class="box"><div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Проект</th><th>Срок</th><th>Статус</th><th>Главный</th>${moneyVis()?'<th class="num">План</th><th class="num">Получено</th><th class="num">Остаток</th>':''}</tr></thead><tbody>${ps.map(p=>`<tr class="clk" data-proj="${p.id}"><td class="wrap">${esc(p.name)}</td><td>${fmtD(p.from)} – ${fmtD(p.to)}</td><td>${pill(p.status,PRS)}</td><td>${esc(empName(p.lead))}</td>${moneyVis()?`<td class="num">${p.plan?fmtM(p.plan):'<span class="faint">не задан</span>'}</td><td class="num">${fmtM(projPaid(p))}</td><td class="num">${p.plan?fmtM(projLeft(p)):'—'}</td>`:''}</tr>`).join('')}</tbody></table></div></div>`
        :`<div class="state">${ic('briefcase','lg')}<b>Проектов пока нет</b><span>Проект — разовая работа для контрагента со сроком, исполнителями и оплатой (например, восстановление учёта).</span>${add?`<button class="btn cta" id="cp-proj">${ic('plus')}Новый проект</button>`:''}</div>`}
    if(st.tab==='hist'){const hs=HIST.filter(h=>h.cp===c.id).sort((a,b)=>a.at<b.at?1:-1).slice(0,80);b=`<div class="box"><ul class="tl">${hs.map(h=>`<li><span class="t">${fmtD(h.at.slice(0,10))}<br>${h.at.slice(11)}</span><span>${h.ent==='r'?`<b>${esc((()=>{const r=REPORTS.find(x=>x.id===h.id);return r?T[r.t].short+' '+r.plabel:''})())}</b> · `:''}${esc(h.what)}<br><span class="w">${esc(whoName(h.who))}</span></span></li>`).join('')||'<li><span></span><span class="faint">Изменений пока не было</span></li>'}</ul></div>`}
    return {head:feeAccOk(c)?`<button class="btn sm hd-btn" id="cp-feeacc" title="Принять оплату за обслуживание" aria-label="Принять оплату за обслуживание">${ic('wallet','sm')}<span class="bl">Принять оплату</span></button>`:'',title:esc(c.name)+(c.archived?' <span class="tag">архив</span>':''),sub:`ИНН <span class="mono">${c.inn}</span> · ${esc(c.regime||'режим не указан')}${c.paused?' · <span class="yellow strong">обслуживание приостановлено</span>':''}${c.kind==='oneoff'?' · разовый контрагент':''}${c.overdue?` · <span class="red strong">просрочено отчётов: ${c.overdue}</span>`:''}`,
      body:cardTabs(tabs,st.tab,'ct')+b,
      foot:`<button class="btn" id="cp-more">${ic('more','sm')}Действия</button><div class="grow"></div><button class="btn cta" id="cp-done">Готово</button>`,
      mount(el,mm){const q=s=>el.querySelector(s);
        ckHit('cp.'+st.tab);{const on=el.querySelector('.tabs .tab.on'),t=on&&on.parentElement;if(t&&t.scrollWidth>t.clientWidth)t.scrollLeft=on.offsetLeft-t.offsetLeft-(t.clientWidth-on.offsetWidth)/2}
        if(st.tab==='kpi')kpiCardMount(el,c,st,mm);
        // Несохранённый подбор отчётов не теряется молча: при уходе с вкладки и по «Готово» — вопрос
        const pkLeave=go=>st.tab==='pick'&&pkCpDirty(c,st)?confirmDlg({title:'Подбор не применён',text:'Отмеченные отчёты и основания не сохранены. Уйти без сохранения?',ok:'Уйти без сохранения',danger:true,run:()=>{st.pk=null;go()}}):go();
        bindCardTabs(el,'ct',k=>pkLeave(()=>{st.tab=k;mm.draw();const mb=el.querySelector('.mb');if(mb)mb.scrollTop=0}));
        q('#cp-done').onclick=()=>pkLeave(()=>mm.close());
        if(st.tab==='pick')pkCpMount(el,c,st,()=>mm.draw());
        q('#cp-more').onclick=e=>menu(e.currentTarget,cpActions(c).filter(x=>x.label!=='Открыть карточку'&&x.label!=='Подобрать отчёты'));
        if(q('#cp-resp'))q('#cp-resp').onclick=()=>respDlg([c]);
        if(q('#cp-assign'))q('#cp-assign').onclick=()=>assignDlg(c);if(q('#cp-pick'))q('#cp-pick').onclick=()=>{st.tab='pick';mm.draw();const mb=el.querySelector('.mb');if(mb)mb.scrollTop=0};
        sfCardMount(el,c,()=>mm.draw());pgMount(el,c,()=>mm.draw());
        if(q('#cp-ben'))q('#cp-ben').onclick=()=>benPickDlg({cx:c,cp:c,ben:c.ben||[],dates:c.benDates||{},edit:can('createCp')&&!c.archived,title:c.name,onApply:({ben,dates})=>{const was=JSON.stringify([c.ben||[],c.benDates||{}]),ov=cpOvMap(c);c.ben=[...ben];c.benDates=dates;if(!Object.keys(dates).length)delete c.benDates;
          if(JSON.stringify([c.ben,c.benDates||{}])===was)return toast('Без изменений');touch(c);log('cp',c.id,'Льготы и особые статусы: '+(c.ben.join(', ')||'нет'),c.id);const n=cpRedue(c,ov);refreshAll();toast('Льготы и статусы сохранены'+(n?`. Сроки по статусу изменены у ${n} ${plural(n,'отчёта','отчётов','отчётов')}`:''))}});
        $$('[data-nnrm]',el).forEach(b=>b.onclick=()=>{const sel=new Set(c.assign.filter(a=>!a.to).map(a=>a.t));b.dataset.nnrm.split(',').forEach(id=>sel.delete(id));pkConfirm(c,sel,{},r=>{refreshAll();if(r)toast(`Снято отчётов: ${r.rem.length}`)})});
        el.querySelectorAll('[data-asg]').forEach(b=>b.onclick=()=>{const a=c.assign.find(x=>x.t===b.dataset.asg&&!x.to);if(a)asgDlg(c,a)});
        if(q('#cp-pays'))q('#cp-pays').onchange=e=>{c.paysTo=e.target.value;OPS.filter(o=>o.cp===c.id&&!o.self).forEach(o=>o.holder=c.paysTo==='org'?'org':c.resp);log('cp',c.id,'Деньги на налоги: '+(c.paysTo==='org'?'на счёт организации':'на кошелёк ответственного'),c.id);refreshAll();toast('Сохранено')};
        if(q('#cp-needf'))q('#cp-needf').onchange=e=>{c.needInFile=e.target.checked;touch(c);log('cp',c.id,c.needInFile?'Включено: обязательно требовать прикрепления при поступлении от контрагента':'Выключено требование файла при поступлении',c.id);toast('Сохранено')};
        if(q('#cp-one'))q('#cp-one').onchange=e=>{c.oneSum=e.target.checked;log('cp',c.id,c.oneSum?'Отмечено: платит одной суммой (налоги и обслуживание)':'Снята отметка «Платит одной суммой»',c.id);toast('Сохранено')};
        if(q('#cp-per'))q('#cp-per').onchange=e=>{st.period=e.target.value;mm.draw()};
        if(q('#cp-in'))q('#cp-in').onclick=()=>inDlg(c);
        if(q('#cp-bonus'))q('#cp-bonus').onclick=e=>e.currentTarget.dataset.why?toast(e.currentTarget.dataset.why,'lock',true):moneyOpDlg(c,'bonus');
        if(q('#cp-refund'))q('#cp-refund').onclick=e=>e.currentTarget.dataset.why?toast(e.currentTarget.dataset.why,'lock',true):moneyOpDlg(c,'refund');if(q('#cp-xfer'))q('#cp-xfer').onclick=()=>xferDlg(c);
        if(q('#cp-tariff'))q('#cp-tariff').onclick=()=>tariffDlg(c);
        if(q('#cp-feepay'))q('#cp-feepay').onclick=()=>feePayDlg(c);if(q('#cp-feeacc'))q('#cp-feeacc').onclick=()=>feePayDlg(c);
        if(q('#cp-feewa'))q('#cp-feewa').onclick=()=>waDlg({cp:c,fee:true});
        if(q('#cp-file'))q('#cp-file').onchange=e=>{const f=[...e.target.files].map(x=>x.name);f.forEach(n=>FUP.add(n));c.files.push(...f);log('cp',c.id,'Прикреплены файлы: '+f.join(', '),c.id);mm.draw();toast('Файлы прикреплены','clip')};
        $$('[data-rep]',el).forEach(x=>x.onclick=()=>openReport(REPORTS.find(r=>r.id===+x.dataset.rep)));
        if($('#cc-task',el))$('#cc-task',el).onclick=()=>taskDlg(null,{cp:c.id});
        $$('[data-task]',el).forEach(x=>x.onclick=()=>openTask(allTasks().find(t=>t.id===x.dataset.task)));
        if(q('#cp-ugns'))q('#cp-ugns').onchange=e=>{const old=c.ugns;c.ugns=e.target.value||null;log('cp',c.id,'УГНС: '+(ugnsLabel(c.ugns)||'не указан'),c.id);const u=ugApply(c,old);refreshAll();
          toast(u.add.length||u.drop.length?`${ugMsg(u.add,u.drop)}${u.n?`. Сроки по статусу изменены у ${u.n} ${plural(u.n,'отчёта','отчётов','отчётов')}`:''}`:'Сохранено')};
        if(q('#cp-svc'))q('#cp-svc').onclick=()=>serviceDlg(null,c);
        if(q('#cp-in2'))q('#cp-in2').onclick=()=>inDlg(c);
        if(q('#cp-proj'))q('#cp-proj').onclick=()=>projectDlg(null,c);
        $$('[data-proj]',el).forEach(x=>x.onclick=()=>openProject(PROJECTS.find(p=>p.id===x.dataset.proj)));
        $$('[data-file]',el).forEach(x=>x.onclick=()=>openFile(allFiles().find(f=>f.id===x.dataset.file)));
        if(st.tab==='fin')grid(q('#cpf'),{id:'cp-fin',audit:false,cols:finCols(),rows:()=>finRows().filter(x=>x.cp===c.id),title:'what',noun:['операция','операции','операций'],sort:{key:'date',dir:-1},search:false,open:openFinRow,actions:finActions,empty:{icon:'coins',title:'Операций пока нет'}});
        if(st.tab==='reports')repGrid(q('#cpr'),'cp-rep',()=>REPORTS.filter(r=>r.cp===c.id&&!r.superseded),{compact:true,cfg:{search:false,preset:null,sort:{key:'due',dir:-1},simulateLoad:false}});
      }};
  }});
}
function tariffDlg(c){const nm=addMonths(ym(TODAY),1);const ct=curTariff(c);
  openModal({form:true,render:()=>({title:'Новая ставка обслуживания',sub:esc(c.name),body:`<div class="form">${fld('Сумма, сом',inp('tf-sum',ct?ct.amount:'','inputmode="decimal" class="inp tnum"'),{req:true,id:'tf-sum'})}${fld('Периодичность',sel('tf-per',[['M','В месяц'],['Y','В год (одна оплата)']],ct?ct.per||'M':'M'),{id:'tf-per',hint:'Годовая ставка начисляется раз в год, в месяце «действует с»'})}${fld('Действует с месяца',inp('tf-from',nm,`type="month" min="${c.tariffs.length?nm:ym(TODAY)}"`),{req:true,id:'tf-from',hint:c.tariffs.length?'С 1-го числа следующего месяца или позже: текущий месяц уже начислен':'Ставка всегда начинается с 1-го числа'})}${fld('Примечание',inp('tf-note','Повышение с '+ymG(nm).split(' ')[0]),{full:true,id:'tf-note'})}</div><div class="note">${ic('info')}<span>Начисления за прошлые месяцы не пересчитываются. Ставку можно внести заранее — она вступит в силу сама.</span></div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="tf-ok">Добавить в журнал</button>',
    mount(el,m){$('#tf-ok',el).onclick=()=>{const n=parseNum(val(el,'tf-sum'));const f=val(el,'tf-from');if(!setErr(el,'tf-sum',isNaN(n)||n<0?'Введите сумму':''))return;
      if(!setErr(el,'tf-from',!f?'Укажите месяц':c.tariffs.some(t=>t.from===f)?'На этот месяц ставка уже есть: ставка меняется не чаще раза в месяц':f<ym(TODAY)?'Прошлые месяцы не меняются':c.tariffs.length&&f===ym(TODAY)?'Ставка меняется со следующего месяца: текущий месяц уже начислен':''))return;
      const per=val(el,'tf-per')||'M';c.tariffs.push({amount:n,per,from:f,by:S.me,at:TODAY,note:val(el,'tf-note')});log('cp',c.id,`Новая ставка ${som(n)} ${per==='Y'?'в год':'в месяц'} с ${ymG(f)}`,c.id);m.close();refreshAll();toast('Ставка добавлена в журнал')}}})});
}
/* «Принять оплату за обслуживание» (решение заказчика 24.10.2026): сумма по умолчанию — долг, делится на неоплаченные начисления от старых к новым,
   излишек — аванс, он сам засчитывается в следующие начисления. edit — та же форма для «Изменить» в окне оплаты */
const feeAccOk=c=>feat('fee')&&can('fee')&&can('tariff')&&!!c&&c.kind!=='oneoff'&&!c.archived&&feeMonths(c).some(m=>feeCharge(c,m)>0);
// Куда поступила оплата за обслуживание: счета организации с назначением «Обслуживание» (основной — первым), ключ — accKey: «acc:<счёт>» или «ph:<номер>»
const fpTo=()=>{const l=orgAccs('fee').slice().sort((a,b)=>(b.mainFee?1:0)-(a.mainFee?1:0));return [...l.map(a=>[accKey(a),`Счёт организации · ${rqProv(a)}${a.kind==='phone'?' · по номеру '+rqNum(a):''}${a.mainFee?' (основной)':''}`]),...(l.length?[]:[['org','Счёт организации']]),['owner','Владельцу организации']]};
const fpToName=t=>t==='owner'?'владельцу организации':(()=>{const a=t&&/^(acc|ph):/.test(t)&&ORG.accounts.find(x=>accKey(x)===t);return a?`счёт организации · ${rqProv(a)}, ${a.kind==='phone'?'по номеру '+rqNum(a):'р/с '+a.acc}`:'счёт организации'})();
function fpWhat(f){const al=fpAlloc(f),adv=fpAdv(f);return (al.length?'Обслуживание за '+al.map(x=>ymLabel(x.m)).join(', '):'Аванс за обслуживание')+(al.length&&adv?` · аванс ${som(adv)}`:'')}
function feePayDlg(c,edit){if(!c)return;const own={};if(edit)fpAlloc(edit).forEach(x=>{own[x.m]=(own[x.m]||0)+x.a});
  // Сколько уже получено за месяц без этой оплаты: свои оплаты месяца и чужой аванс
  const base=m=>(c.feePaid[m]||0)-(own[m]||0);const sp=feeAdvSplit(c,FEEPAYS.filter(f=>f.cp===c.id&&!f.del&&f!==edit).reduce((a,f)=>a+fpAdv(f),0),base);
  const got=m=>base(m)+(sp.use[m]||0),left=m=>Math.max(0,Math.round((feeCharge(c,m)-got(m))*100)/100);
  const ms=feeMonths(c).filter(m=>left(m)>0||own[m]);const debt=ms.reduce((a,m)=>a+left(m),0);
  const st={sum:edit?edit.amount:(c.feeDebt||debt||''),date:edit?edit.date:TODAY,to:edit?edit.to||'org':(fpTo()[0]||[])[0],note:edit?edit.note||'':'',why:'',rows:{},manual:false};
  // От старых к новым; при изменении сначала месяцы, которые эта оплата уже закрывала
  const order=edit?[...ms.filter(m=>own[m]),...ms.filter(m=>!own[m])]:ms;
  const auto=()=>{let t=parseNum(st.sum);if(isNaN(t))t=0;st.rows={};order.forEach(m=>{const x=Math.min(t,left(m));if(x>0){st.rows[m]=Math.round(x*100)/100;t-=x}})};
  if(edit)fpAlloc(edit).forEach(x=>{st.rows[x.m]=(st.rows[x.m]||0)+x.a});else auto();
  const sel0=fpTo();if(edit&&!sel0.some(o=>o[0]===st.to))sel0.unshift([st.to,fpToName(st.to)]);
  openModal({form:true,size:'mid',render:mm=>({title:edit?'Изменить оплату за обслуживание':'Принять оплату за обслуживание',sub:`${esc(c.name)} · ${c.feeDebt?`долг ${som(c.feeDebt)}`:debt?`к оплате ${som(debt)}`:'долгов нет'}${c.feeAdv&&!edit?` · аванс ${som(c.feeAdv)}`:''}`,
    body:`<div class="form">${fld('Сумма, сом',inp('fp-sum',st.sum===''?'':String(st.sum),'inputmode="decimal" class="inp tnum"'),{req:true,id:'fp-sum',hint:c.feeDebt?`Подставлен долг за обслуживание: ${som(c.feeDebt)}`:''})}${fld('Дата',inp('fp-date',st.date,`type="date" max="${TODAY}"`),{req:true,id:'fp-date'})}
      ${fld('Куда поступили деньги',sel('fp-to',sel0,st.to),{id:'fp-to',full:true,hint:'Плата за обслуживание поступает только организации: на её счёт или владельцу'})}</div>
    <div class="box flat"><h3>За какие месяцы<span class="grow"></span>${ms.length?`<button class="btn sm" id="fp-auto" type="button">${ic('list','sm')}От старых к новым</button>`:''}</h3>
      ${ms.length?`<div class="tbl-wrap"><table class="mini"><thead><tr><th>Месяц</th><th class="num">Начислено</th><th class="num">Уже оплачено</th><th class="num" style="width:140px">Распределить</th><th>Станет</th></tr></thead><tbody>${ms.map(m=>`<tr><td>${esc(ymLabel(m))}${feeDue(c,m)<TODAY&&left(m)>0?' <span class="tag red">просрочено</span>':''}</td><td class="num">${fmtM(feeCharge(c,m))}</td><td class="num">${fmtM(got(m))}</td><td class="num"><input class="inp tnum" data-fpm="${m}" value="${st.rows[m]!=null?st.rows[m]:''}" inputmode="decimal" style="max-width:120px;margin-left:auto;text-align:right" aria-label="Распределить на ${esc(ymLabel(m))}"></td><td data-fps="${m}"></td></tr>`).join('')}</tbody></table></div>`:'<span class="faint">Неоплаченных начислений нет — вся сумма станет авансом и сама засчитается в следующие начисления.</span>'}
      <div id="fp-line" class="row"></div></div>
    <div class="form">${fld('Файл: скрин перевода, квитанция',`<input class="inp" type="file" id="fp-f" multiple>`,{full:true,id:'fp-f',hint:edit&&(edit.files||[]).length?`Уже приложено: ${edit.files.length}`:''})}${fld('Примечание',inp('fp-note',st.note),{full:true,id:'fp-note'})}
      ${edit?fld('Причина изменения',`<textarea class="inp" id="fp-why" style="min-height:56px" placeholder="Например: ошибка в сумме">${esc(st.why)}</textarea>`,{full:true,id:'fp-why',hint:'Обязательна, если меняются сумма, дата, месяцы или куда поступили деньги'}):''}</div>`,
    foot:`<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="fp-ok">${ic('wallet','sm')}${edit?'Сохранить':'Принять оплату'}</button>`,
    mount(el){const line=$('#fp-line',el);
      const calc=()=>{const t=parseNum(st.sum),T_=isNaN(t)?0:t;const d=Object.values(st.rows).reduce((a,v)=>a+(+v||0),0);
        $$('[data-fps]',el).forEach(td=>{const m=td.dataset.fps,a=+st.rows[m]||0;td.innerHTML=!a?'<span class="faint">—</span>':a>left(m)+0.001?`<span class="pill red sm">больше долга</span>`:got(m)+a>=feeCharge(c,m)-0.001?`<span class="pill green sm">${ic('ok')}оплачено</span>`:`<span class="pill yellow sm">частично</span>`});
        line.innerHTML=`<span>Распределено: <b class="tnum">${fmtM(d)}</b></span><div class="grow"></div>${d>T_+0.001?`<span class="pill red">${ic('alert')}больше суммы на ${fmtM(d-T_)}</span>`:T_-d>0.001?`<span class="pill blue">${ic('info')}аванс ${fmtM(T_-d)} — засчитается в следующие начисления</span>`:T_>0?`<span class="pill green">${ic('ok')}сходится</span>`:''}`;return {t,d}};
      calc();
      $('#fp-sum',el).oninput=e=>{st.sum=e.target.value;if(!st.manual){auto();$$('[data-fpm]',el).forEach(i=>i.value=st.rows[i.dataset.fpm]!=null?st.rows[i.dataset.fpm]:'')}calc()};
      $('#fp-date',el).oninput=e=>{st.date=e.target.value};$('#fp-to',el).onchange=e=>{st.to=e.target.value};$('#fp-note',el).oninput=e=>{st.note=e.target.value};if($('#fp-why',el))$('#fp-why',el).oninput=e=>{st.why=e.target.value};
      $$('[data-fpm]',el).forEach(i=>i.oninput=()=>{st.manual=true;const n=parseNum(i.value);if(isNaN(n))delete st.rows[i.dataset.fpm];else st.rows[i.dataset.fpm]=n;calc()});
      if($('#fp-auto',el))$('#fp-auto',el).onclick=()=>{st.manual=false;auto();mm.draw()};
      $('#fp-ok',el).onclick=()=>{const {t,d}=calc();const bad=Object.entries(st.rows).some(([m,v])=>v<0||v>left(m)+0.001);
        if(!setErr(el,'fp-sum',isNaN(t)||t<=0?'Введите сумму больше нуля':bad?'В строке месяца сумма больше долга за этот месяц':d>t+0.001?`Распределено больше суммы на ${som(d-t)}`:''))return;
        if(!setErr(el,'fp-date',!st.date?'Укажите дату':st.date>TODAY?'Дата не может быть позже сегодняшней':''))return;
        const alloc=Object.entries(st.rows).filter(([,v])=>v>0).sort((a,b)=>a[0]<b[0]?-1:1).map(([m,a])=>({m,a})),files=[...$('#fp-f',el).files].map(x=>x.name);files.forEach(n=>FUP.add(n));
        const txt=al=>(al.length?al.map(x=>`${ymLabel(x.m)} — ${fmtM(x.a,false)}`).join(', '):'')+(t-al.reduce((a,x)=>a+x.a,0)>0.001?`${al.length?', ':''}аванс — ${fmtM(t-al.reduce((a,x)=>a+x.a,0),false)}`:'');
        if(edit){const al0=fpAlloc(edit),ch=[];if(Math.abs(t-edit.amount)>0.001)ch.push(`сумма ${fmtM(edit.amount)} → ${fmtM(t)} сом`);if(st.date!==edit.date)ch.push(`дата ${fmtD(edit.date)} → ${fmtD(st.date)}`);
          const t0=txt(al0).replace(/аванс — [\d\s,]+$/,''),t1=txt(alloc).replace(/аванс — [\d\s,]+$/,'');if(t0!==t1)ch.push(`месяцы «${t0||'аванс'}» → «${t1||'аванс'}»`);if(st.to!==(edit.to||'org'))ch.push(`куда: ${fpToName(edit.to||'org')} → ${fpToName(st.to)}`);
          if(!setErr(el,'fp-why',ch.length&&!st.why.trim()?'Укажите причину: меняются '+ch.map(x=>x.split(/[ :]/)[0]).join(', '):''))return;
          al0.forEach(x=>{c.feePaid[x.m]=(c.feePaid[x.m]||0)-x.a});alloc.forEach(x=>{c.feePaid[x.m]=(c.feePaid[x.m]||0)+x.a});const nch=st.note!==(edit.note||'');
          Object.assign(edit,{amount:t,alloc,month:alloc.length?alloc[0].m:null,date:st.date,to:st.to,note:st.note});(edit.files=edit.files||[]).push(...files);if(ch.length||nch)edit.edited=true;touch(edit);
          HIST.push({at:nowStamp(),who:S.me,ent:'fp',id:edit.id,cp:c.id,what:`Изменено: ${[...ch,nch?'примечание':'',files.length?'добавлены файлы: '+files.join(', '):''].filter(Boolean).join('; ')||'без изменений'}${ch.length?'. Причина: '+st.why.trim():''}`})}
        else{const f=born({id:fpId(),cp:c.id,amount:t,alloc,month:alloc.length?alloc[0].m:null,date:st.date,by:S.me,holder:'org',to:st.to,note:st.note,files});FEEPAYS.push(f);alloc.forEach(x=>{c.feePaid[x.m]=(c.feePaid[x.m]||0)+x.a});
          log('fp',f.id,`Оплата за обслуживание ${som(t)}: ${txt(alloc)}`,c.id)}
        mm.close();refreshAll();toast(edit?'Оплата изменена':'Оплата за обслуживание принята','wallet')}}})});
}

/* Внутренние отчёты: периодичность и срок по контрагенту */
function intRows(ids,cfgOf){return `<div class="tbl-wrap"><table class="mini"><thead><tr><th>Отчёт</th><th>Периодичность</th><th>Срок: число</th><th>Месяц</th><th>Получится</th></tr></thead><tbody>${ids.map(id=>{const t=T[id],c=cfgOf(id);const e=tEff(t,Object.assign({t:id},c));const s='style="min-height:30px;padding:3px 8px;width:auto"';
  return `<tr><td><b>${esc(t.short)}</b></td><td>${sel('ip-'+id,[['M','Месяц'],['Q','Квартал'],['H','Полугодие'],['Y','Год']],c.per,`data-iper="${id}" ${s}`)}</td><td><input class="inp tnum" data-iday="${id}" value="${c.day}" inputmode="numeric" style="width:64px;min-height:30px;padding:3px 8px" aria-label="Число"></td><td>${c.per==='Y'?sel('im-'+id,MONTHS_G.map((x,i)=>[i+1,x+' след. года']),c.mo,`data-imo="${id}" ${s}`):sel('im-'+id,[[0,'того же периода'],[1,'1-го месяца после'],[2,'2-го месяца после'],[3,'3-го месяца после']],c.mo,`data-imo="${id}" ${s}`)}</td><td class="muted" style="white-space:normal">${esc(ruleText(e))}</td></tr>`}).join('')}</tbody></table></div>`}
function bindInt(el,cfgOf,m){
  $$('[data-iper]',el).forEach(s=>s.onchange=()=>{const c=cfgOf(s.dataset.iper);c.per=s.value;c.mo=c.per==='Y'?4:1;m.draw()});
  $$('[data-imo]',el).forEach(s=>s.onchange=()=>{cfgOf(s.dataset.imo).mo=+s.value;m.draw()});
  $$('[data-iday]',el).forEach(i=>i.onchange=()=>{const n=parseInt(i.value,10);if(n>=1&&n<=31)cfgOf(i.dataset.iday).day=n;m.draw()})}

